<?php require_once "config/database.php";require_once "includes/functions.php";$pageTitle="Wishlist";$items=[];foreach($_SESSION["wishlist"]??[] as $id){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$id]);if($p=$s->fetch())$items[]=$p;}require "includes/header.php";?><section class="section"><div class="container"><div class="eyebrow">Saved For Later</div><h1>Wishlist</h1><div class="grid"><?php if(!$items):?><div class="empty" style="grid-column:1/-1">Your wishlist is empty.</div><?php endif;?><?php foreach($items as $p):?><article class="card"><img src="<?=e($p["image"])?>" alt=""><div class="body"><h3><?=e($p["name"])?></h3><div class="price">₹<?=number_format((float)$p["price"],2)?></div><div class="actions"><form action="actions/add_to_cart.php" method="post"><input type="hidden" name="product_id" value="<?=$p["id"]?>"><button class="btn">Add to Cart</button></form><a class="btn danger" href="actions/wishlist.php?id=<?=$p["id"]?>&remove=1">Remove</a></div></div></article><?php endforeach;?></div></div></section><?php require "includes/footer.php";?>